import{_ as t}from"./chunks/0c32175a0d0d6b6db9ea.BnJw4KYW.js";import{_ as o,o as i,c as a,a5 as n}from"./chunks/framework.DNkHA0lr.js";const m=JSON.parse('{"title":"This Is Why Your Life Sucks (How To Reinvent Yourself)","description":"","frontmatter":{"title":"This Is Why Your Life Sucks (How To Reinvent Yourself)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md","filePath":"en/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md"}'),r={name:"en/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself.md"};function s(h,e,p,u,l,d){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="this-is-why-your-life-sucks-how-to-reinvent-yourself" tabindex="-1">This Is Why Your Life Sucks (How To Reinvent Yourself) <a class="header-anchor" href="#this-is-why-your-life-sucks-how-to-reinvent-yourself" aria-label="Permalink to &quot;This Is Why Your Life Sucks (How To Reinvent Yourself)&quot;">​</a></h1><p>Dan Koe · 2023-10-13 · <a href="https://thedankoe.com/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/this-is-why-your-life-sucks-how-to-reinvent-yourself">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/SKI8FcKXQkg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>I think often about one of the darkest periods of my life.</p><p>The funny thing is, I didn’t know it was my darkest period.</p><p>At the time, it was normal.</p><p>It was my standard.</p><p>My “good” days then are my terrible days now… and that was normal.</p><p>So many people have no idea how much better they could feel. They don’t realize that their “normal” state is bottom of the barrel.</p><p>I would start my days at 10am.</p><p>I would drive straight to Mcdonald’s to pick up 2 sausage, egg, and cheese McMuffins with an iced coffee.</p><p>I would instantly feel like garbage, lay back down, and binge-watch episodes of The Office until I got hungry again.</p><p>I was taking online classes at the time. Of course, I didn’t know how to manage myself. I saw the “freedom” of online classes as an excuse to adopt self-destructive habits and slowly die in my comfortable hole.</p><p>I barely did my schoolwork.</p><p>I would log on last minute and complete the bare minimum of the assignments (I still passed with As and Bs).</p><p>At night, I would spend 5-7 hours playing League Of Legends. With or without friends, it didn’t matter. I was just numbing my mind at this point.</p><p>This was all to illustrate one point:</p><p>The difference between video games and real life is fake risk and real risk.</p><p>Real pain.<br> Real fear.<br> Real sacrifice.<br> The things that allow pleasure, love, and results to exist.</p><p>In a video game, you can fail without repercussion.</p><p>In life, you can’t just hide behind your screen and hope there won’t be failure.</p><p>In a video game, we trick our minds into thinking it’s making progress.</p><p>I was doing the same thing in life.</p><p>The sleeping-in, fast food, and Netflix binges kept me in a drip-fed dopamine sedation so that I didn’t feel the need to pursue anything greater.</p><p>Everything was fine, because I let it be fine.</p><p>My life sucked, because I let it suck.</p><p>Before we start, The Art Of Focus Keepsake Box is available for preorder:</p><p><img src="'+t+'" alt=""></p><ul><li>The Keepsake Hardcover – we are only printing 2000 copies.</li><li>The digital download of the book so you can be the first to read.</li><li>The audiobook version when it is recorded and uploaded.</li><li>The FOCI Planner to deconstruct your ideal future into priority tasks.</li><li>The FOCI Coin to remember to act with intention.</li><li>The Digital Transformation Center with 12 hours of modern entrepreneurship trainings.</li><li>The Private Community for updates, discussion, and networking.</li><li>A private invitation to 6+ speaker two-weekend-long virtual event on The Future Of Work</li></ul><p>The price increases twice leading up to the release date. <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">Preorder your copy here.</a></p><h2 id="tiny-choices" tabindex="-1">Tiny Choices <a class="header-anchor" href="#tiny-choices" aria-label="Permalink to &quot;Tiny Choices&quot;">​</a></h2><p>Your life sucks because of the thousands of tiny choices you made over the past year.</p><p>You didn’t make the choices that led to a purposeful career.</p><p>You didn’t make the choices that led to fulfilling relationships.</p><p>You didn’t make the choices that led to a healthy and aesthetic body.</p><p>“But Dan, what about genetics and where I was born and working a job that doesn’t allow me enough time blah blah blah”</p><p>Yeah, those things play a role.</p><p>But you just made another tiny choice to close your mind off to what you <em>can</em> do in your situation.</p><blockquote><p>The ability to choose cannot be taken away or even given away—it can only be forgotten. – Greg McKeown</p><p>Essentialism</p></blockquote><p>It’s not difficult to look around and see that you aren’t a special case. There are thousands like you that have turned their situation around.</p><p>The quality of your life one year from now will depend on the tiny choices that compound into that life.</p><p>You don’t have to make perfect choices.</p><p>It’s actually better if you make mistakes.</p><p>The greatest risk is no risk at all, because how else would you fail?</p><p>Without failure, improvement is literally impossible.</p><p>Without improvement, you don’t have an aim for your life.</p><p>Without an aim for your life, everything becomes meaningless.</p><p>Becoming a better person is how you live with purpose.</p><h2 id="big-standards" tabindex="-1">Big Standards <a class="header-anchor" href="#big-standards" aria-label="Permalink to &quot;Big Standards&quot;">​</a></h2><p>Broke people are okay with being broke until something catastrophic happens.</p><p>And it is much more likely for a catastrophic event to happen to them.</p><p>Their car blows up because it’s old and unmaintained.</p><p>Someone breaks into their house in a bad neighborhood.</p><p>Their parents get sick and they can’t help because of their low income.</p><p>Of course, they have some motivation to make money at this point, but they think it’s too late when the catastrophic event happens. They didn’t prepare.</p><p>So they get trapped in an endless cycle of <em>“I should’ve started sooner.”</em></p><p>Eventually, things equalize. The stress in their life lowers. They start to enjoy their mindless comforts again. Waiting for another catastrophe to break them down.</p><p>Successful people use these events to change who they are.</p><p>Who they are determines their standards and values.</p><p>Their standards and values determine the tiny choices they make.</p><p>If you’re okay with having $5 in your bank account, you won’t see that as a problem.</p><p>If you’re okay with having $100,000 in your bank account, you will see anything less than that as a problem that needs to be fixed.</p><p>Problems frame your perception – I talk about this in <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">my book</a>.</p><p>You begin to notice more money-making opportunities.</p><p>Your Google searches change to things like “how to make an extra $1,000/month.”</p><p>You start having conversations about money with your friends.</p><p>All of these tiny choices begin to compound into results.</p><p>You rewire your thinking patterns based on your intentional search for specific information relating to the problem you are facing.</p><p>The information you consume highly impacts your identity and thus your standards.</p><p>If you surround yourself with people – physical or digital – that make it seem like it’s “okay” to be 100 pounds overweight, have zero money, work a job you hate, stay with a partner you despise, get drunk every night, and the rest… how do you think your life will end up?</p><p>If your standards require you to eat from Whole Foods, you will look at McDonald’s meals in disgust.</p><p>If your standards require you to work like a CEO, you will look at low-level grunt work as a problem that must be fixed through skill acquisition, education, prioritization, and outsourcing.</p><p>You obviously can’t solve all of the problems in your life immediately.</p><p>You can’t escape your situation right now.</p><p>You need a plan. An aim. A way out.</p><p>And by sticking to this plan, I promise that the journey will be more enjoyable than the outcome of that thing.</p><p>As Nietzsche would say:</p><blockquote><p>“Happiness is the feeling that power increases – that resistance is being overcome.”</p></blockquote><h2 id="the-standards-of-who-you-want-to-become" tabindex="-1">The Standards Of Who You Want To Become <a class="header-anchor" href="#the-standards-of-who-you-want-to-become" aria-label="Permalink to &quot;The Standards Of Who You Want To Become&quot;">​</a></h2><p>Most people take the bare minimum approach to life.</p><p>Quick money, quick sex, quick pleasure, no commitment, no depth, no failure.</p><p>The easier you try to make your life the harder it’s going to be.</p><p>The way out of mindless living is to adopt the standards of who you want to become.</p><p>How much money do you want to make?</p><p>What kind of work will bring you fulfillment?</p><p>What is your ideal relationship, for friends or a partner?</p><p>How do you want to look and feel?</p><p>You must go beyond the bare minimum of survival.</p><p>Commit to having a reason behind your actions.</p><p>If you don’t know why you are doing something, why are you doing it? And if you know why, why are you ignoring it?</p><p>Are you advancing humanity by handing out 40 triple-pumped mocha cappuccinos working at Starbucks? Or are you making humanity sick and overweight?</p><p>Why haven’t you begun pursuing a more purposeful career or starting a business?</p><p>Do you know why you are shoveling food down your throat? Do you understand how each nutrient interacts with your biology and creates a healthy state?</p><p>Why haven’t you begun educating yourself on health and training?</p><p>You live in your body. It should be considered your full-time job to learn about it.</p><p>Do you know why you are going through the motions with a partner that was easy to get with? Do you see yourself with them for 40 more years?</p><p>Why haven’t you improved your social skills to the point of being able to attract a better partner?</p><p>It’s cliche, but you have one shot at this life thing.</p><p>The only person that can stop you from living a meaningless existence is yourself.</p><h2 id="the-power-of-the-internet" tabindex="-1">The Power Of The Internet <a class="header-anchor" href="#the-power-of-the-internet" aria-label="Permalink to &quot;The Power Of The Internet&quot;">​</a></h2><p>Let’s break down what creates better choices:</p><p>Learning is the fundamental human drive.</p><p>At birth, you are an information sponge.</p><p>Your parents, friends, society, teachers, and bosses all project their worldview on you.</p><p>Where did they get their worldview? From the same people, unless they questioned it.</p><p>This is all that you know.</p><p>If we could put a number on it, you know less than 1% of the information available in the world. Probably closer to less than 0.001%.</p><p>This information creates reference points in reality.</p><p>It is how you distinguish yourself from others.</p><p>It creates your identity.</p><p>Your identity limits what information you notice, because you’ve only learned so much. You won’t notice certain things if you haven’t learned the information that bridges what it is with what you know. You won’t understand intermediate information if you haven’t learned beginner information. You can’t advance from level 1 to 3. You are missing out on 99% of life for this reason.</p><p>If I was exposed to the information and environment that made me goth, I would notice certain likes and dislikes in music, people, clothing, work opportunities, outlooks on the future, and emotional states.</p><p>As a goth, I won’t notice or even care about profitable business opportunities to experiment with (assuming that I am the stereotypical loner goth who hates the world).</p><p>If I drowned myself in information to reprogram my identity over time, I would spot opportunities related to that identity.</p><p>This brings up the power of the internet.</p><p>You can tend a digital garden or be thrust into a digital swamp.</p><p>We’ve never had access to so much information, and I find it hard to believe that it isn’t shaping identities rapidly and for the worse.</p><p>When you log on to social media, the default action is to follow entertaining accounts and meme pages.</p><p>Almost all of them subject your mind to unwanted tenants that party like it’s a frat house. When the parents come home, they’re devastated by what they see.</p><p>Your awareness is the parents coming home after mindless ideas turn your mind into a swamp.</p><p>Become aware of this now.</p><ol><li><strong>Unfollow anyone who does not serve the conditioning of better standards in your life</strong>. Even if it doesn’t seem like it, and no matter how much you justify it, the people you follow subtly influence your actions. Slowly, then all at once you become someone you may hate.</li><li><strong>Take your time to follow valuable accounts.</strong> Valuable accounts challenge your worldview, make you think outside the box, and educate you on the skills necessary to reach a higher quality of life.</li></ol><p>This is not an overnight process.</p><p>You may not find the information useful at first.</p><p>It takes time to bridge specific ideas that lead to understanding.</p><p>You will probably find it boring… until it’s one of the most interesting things in the world.</p><p>Follow one account.</p><p>Let the algorithm do its work.</p><p>Follow accounts that reply to the first account’s posts.</p><p>With time, you will create an environment that is conducive to your growth.</p><p><em>The only difference between you and the person more successful than you is the consistent intention behind the information they consume.</em></p><p>“But what about taking action???”</p><p>You are acting every day.</p><p>Why?</p><p>Because your mind is programmed with the information conducive to those actions.</p><p>Your identity is forged by the information you’ve been fed, and that alone determines what you perceive as an opportunity to act.</p><p>Surround yourself with the right people and you can achieve anything you want.</p><h2 id="the-path-of-the-value-creator" tabindex="-1">The Path Of The Value Creator <a class="header-anchor" href="#the-path-of-the-value-creator" aria-label="Permalink to &quot;The Path Of The Value Creator&quot;">​</a></h2><p>Why do people keep doing things they hate?</p><p>I’ve always wondered this.</p><p>Not like I’m a special little flower that never got stuck in the trap, but one who feels like he’s escaped and can view the situation from higher up on the mountain until he inevitably falls back down.</p><p>Praying for the weekend.</p><p>Dreading Monday morning.</p><p>Hiding who you are to make conversation with people you don’t like working with.</p><p>Using the internet as an escape.</p><p>Scrolling, clicking, shutting your mind off for just a bit longer, because when it’s on, you don’t like what it’s doing.</p><p>This is the life of the consumer.</p><p>The person who is used by the internet, rather than the one who uses it.</p><p>There’s no escaping this new world.</p><p>You can fight it or flow with it.</p><p>And while the internet is the problem, it’s also the solution.</p><p>You do not have to use the internet to do this, but there is no reason not to.</p><p><em>The last reason your life sucks is because you don’t contribute to humanity.</em></p><p><em>You don’t contribute to humanity because you don’t have something so valuable that you can’t help but share it.</em></p><p><em>You don’t have something valuable to offer because you are ignoring the problems in your life that beg a solution to be created.</em></p><p><em>You are ignoring the problems in your life because you don’t have clarity on how to achieve the goal that will solve them.</em></p><p><em>You don’t have clarity on how to achieve a goal because you have nothing to build. Nothing to frame and guide your learning.</em></p><p>A value creator is someone who has intention behind their inputs and outputs.</p><p>They treat their life like a science project.</p><p>They identify their own problems.</p><p>They educate themselves with the infinite resources available to them on the internet.</p><p>They test the solution on themselves and distribute their experiences with writing.</p><p>They package up the most helpful and streamlined solutions in the form of a product or service.</p><p>That is how they make a living by living with purpose.</p><p>Becoming a creator is the cure for overconsumption.</p><p>I’ve discussed this numerous times in my previous letters. I also break it all down in my book, <a href="https://theartoffocusbox.com/" target="_blank" rel="noreferrer">The Art Of Focus</a>.</p><p>Writing is the vessel for distributing value.</p><p>I write on all platforms. I don’t care to compete with images of my fancy car or lifestyle. I gain a deep sense of fulfillment by using the internet as not only a place to curate good thoughts, but to organize them and share them with others with the ultimate upside of doing what I enjoy for a living. Something that’s in my control.</p><p>This isn’t about becoming famous.</p><p>This isn’t about building a massive following.</p><p>This is about distributing the value you have to offer in a place that can reach anyone with the opportunities that will change your life and career.</p><p>You don’t need a step-by-step course to join the online party.</p><p>Write what you want to write.</p><p>Talk to who you want to talk to.</p><p>Get your name in front of people by not being a ghost.</p><p>Get eyes on your writing so it can spread more and more with time.</p><p>If you really need an extra push, just observe the people you are following for long enough.</p><p>Observe what they write about.</p><p>Observe how they write it.</p><p>Observe who they interact with.</p><p>Observe what they sell to make a living.</p><p>Piece the dots together and begin emulating them.</p><p>If you don’t have an answer, look it up.</p><p>You won’t get all of your answers in an instant.</p><p>Be okay with that.</p><p>If you know you are meant for more, start acting like it.</p><p>You don’t have to write, but I’ve tried it all.</p><p>With writing being the fundamental mode of communication that has survived throughout human existence, it’s a great starting point to discover what you truly want to do.</p><p>Enjoy the rest of your week my friends.</p><p>Dan Koe</p>',190)])])}const f=o(r,[["render",s]]);export{m as __pageData,f as default};
